const a="AES-GCM";function c(e){return btoa(String.fromCharCode(...new Uint8Array(e)))}function y(e,n){const r=new TextEncoder;return crypto.subtle.importKey("raw",r.encode(e),"PBKDF2",!1,["deriveKey"]).then(t=>crypto.subtle.deriveKey({name:"PBKDF2",salt:n,iterations:1e5,hash:"SHA-256"},t,{name:a,length:256},!1,["encrypt","decrypt"]))}async function p(e,n){const r=new TextEncoder,t=crypto.getRandomValues(new Uint8Array(16)),o=crypto.getRandomValues(new Uint8Array(12)),s=await y(n,t),i=await crypto.subtle.encrypt({name:a,iv:o},s,r.encode(e));return{ciphertext:c(i),iv:c(o),salt:c(t)}}export{p as encryptData};
